$sid=services_server_id(); $cat=catalog(true);
function parse_svc($cat){ $src=$_POST['source']??''; $kind=$t=$p='';
 if($src==='tcp'){ $kind=$_POST['t_kind']??''; $t=trim($_POST['t_target']??''); $p=preg_replace('/\D/','',$_POST['t_port']??''); }
 elseif($src==='url'){ $kind=$_POST['u_kind']??''; $t=trim($_POST['u_target']??''); $p=trim($_POST['u_param']??''); }
 else return null;
 $e=$cat[$src][$kind]??null; if(!$e||$t===''||($kind==='contains'&&$p==='')||($kind==='custom'&&$p==='')) return null;
 $iv=iv_post(); if($iv!==null&&(int)$iv===(int)setting($src==='tcp'?'int_tcp':'int_url',$src==='tcp'?30:60)) $iv=null;
 $mu=isset($_POST['mon_up'])?1:0; $mm=isset($_POST['mon_ms'])?1:0; if(!$mu&&!$mm) $mu=1;
 return [$src,$kind,$t,$p,trim($_POST['label']??'')?:($src==='url'?(parse_url($t,PHP_URL_HOST)?:$t):$t),$iv,$mu,$mm]; }
if($_SERVER['REQUEST_METHOD']==='POST'){ $a=$_POST['a']??''; if(server_box_post($sid)){ header('Location: services.php');exit; } $cid=(int)($_POST['cid']??0); $bad=t('Fyll i alla obligatoriska fält (domän/IP eller URL).','Fill in all required fields (domain/IP or URL).');
 if($a==='add_check'){ if($x=parse_svc($cat)) db()->prepare('INSERT INTO server_checks(server_id,source,kind,target,param,label,interval_sec,mon_up,mon_ms) VALUES(?,?,?,?,?,?,?,?,?)')->execute(array_merge([$sid],$x)); else $_SESSION['flash']=$bad; }
 if($a==='edit_check'){ if($x=parse_svc($cat)){ db()->prepare('UPDATE server_checks SET source=?,kind=?,target=?,param=?,label=?,interval_sec=?,mon_up=?,mon_ms=?,last_status=NULL,last_detail=NULL,last_value=NULL,last_data=NULL,last_check=NULL WHERE id=? AND server_id=?')->execute(array_merge($x,[$cid,$sid])); $_SESSION['flash']=t('Ändringarna sparades.','Changes saved.'); } else { $_SESSION['flash']=$bad; header("Location: services.php?edit=$cid");exit; } }
 if($a==='test_check'){ $q=db()->prepare('SELECT c.*,c.target AS host FROM server_checks c WHERE c.id=? AND c.server_id=?'); $q->execute([$cid,$sid]); if($c=$q->fetch()){ $r=exec_check($c); store_result($c,$r); $_SESSION['flash']=($r[0]?'✔ ':'✖ ').$c['label'].': '.$r[1]; } }
 if($a==='toggle_enabled') db()->prepare('UPDATE server_checks SET enabled=1-enabled,last_check=IF(enabled=1,NULL,last_check) WHERE id=? AND server_id=?')->execute([$cid,$sid]);
 if($a==='toggle_hide') db()->prepare('UPDATE server_checks SET hidden=1-hidden WHERE id=? AND server_id=?')->execute([$cid,$sid]);
 if($a==='del_check'){ purge_targets([],[$cid]); } if($a==='del_check') db()->prepare('DELETE FROM server_checks WHERE id=? AND server_id=?')->execute([$cid,$sid]);
 header('Location: services.php');exit; }
$ed=null; if(isset($_GET['edit'])&&is_admin()){ $q=db()->prepare('SELECT * FROM server_checks WHERE id=? AND server_id=?'); $q->execute([(int)$_GET['edit'],$sid]); $ed=$q->fetch()?:null; }
$cs=db()->query("SELECT * FROM server_checks WHERE server_id=$sid ORDER BY ".chk_ord())->fetchAll();
